type Episode={id:string;name:string;lineName:string;url:string;type:string;sortOrder:number};
type Video={id:string;sourceKey:string;title:string;cover?:string;year?:number;category?:string;area?:string;language?:string;desc?:string;director?:string;actors?:string;sourceName?:string;episodes?:Episode[];variants?:{id:string;sourceKey:string;sourceName:string}[]};
type User={id:number;memberNo:string;username:string;displayName?:string;avatarUrl?:string;role:string;pageAccess:string;sourceKeys:string[];permissions:string[];points:number;membership:{name:string;active:boolean;expiresAt?:string}};
const pagePermission=(path:string)=>path==='/'?'home':/^\/(sources|source|category)(\/|$)/.test(path)?'sources':/^\/(detail|player)(\/|$)/.test(path)?'playback':/^\/search(\/|$)/.test(path)?'search':/^\/favorites(\/|$)/.test(path)?'favorites':/^\/history(\/|$)/.test(path)?'history':/^\/recommendations(\/|$)/.test(path)?'recommendations':/^\/discover(\/|$)/.test(path)?'discover':null;
type Settings=Record<string,string>;
const mainCategories=['电影','电视剧','动漫','综艺','纪录片','短剧','体育'];
function MainNavigation({mobile=false,docked=false,user}:{mobile?:boolean;docked?:boolean;user?:User|null}){const location=useLocation();return <nav className={mobile?`category-nav-mobile ${docked?'docked':''}`:'main-navigation'} aria-label={mobile?'移动端分类导航':'主导航'}>{[['/','首页'],['/sources','片库'],...mainCategories.map(name=>['/category/'+name,name]),['/recommendations','今日推荐'],['/discover','热门榜'],['/membership','会员']].filter(([href])=>!user||user.role==='admin'||!pagePermission(href)||user.permissions.includes(pagePermission(href)!)).map(([href,label])=><Link key={href} to={href} aria-current={decodeURIComponent(location.pathname)===href?'page':undefined}>{label}</Link>)}</nav>;}
const API_BASE=import.meta.env.VITE_API_URL||'';

async function api<T=any>(url:string,options?:RequestInit):Promise<T>{const response=await fetch(API_BASE+'/api'+url,{credentials:'include',cache:'no-store',...options});const text=await response.text();let body:any={};try{body=text?JSON.parse(text):{}}catch{throw new Error(`服务器返回了网页而不是 JSON（${response.status}）`)}if(!response.ok)throw new Error(body.error||'请求失败');return body as T}
const normalizeCategory=(value:string)=>String(value||'').toLowerCase().replace(/[\s_\-—·/\\,，、:：()（）【】\[\]]/g,'').replace(/片$|剧$|类$|节目$/g,'');const categoryAliases:Record<string,string>={'国漫':'动漫','国产动画':'动漫','国产动漫':'动漫','番剧':'动漫','大陆剧':'国产剧','国产电视剧':'国产剧','内地剧':'国产剧','香港剧':'港剧','台湾剧':'台剧','美剧':'欧美剧','英剧':'欧美剧','韩剧':'日韩剧','日剧':'日韩剧','综艺节目':'综艺','真人秀':'综艺','脱口秀':'综艺'};const guessCategory=(remote:string,locals:string[])=>{const alias=categoryAliases[String(remote).trim()]||String(remote).trim(),a=normalizeCategory(alias);return locals.find(x=>normalizeCategory(x)===a)||locals.find(x=>a.length>=2&&(a.includes(normalizeCategory(x))||normalizeCategory(x).includes(a)))||''};
const hydrateMissingCovers=<S extends Video[]|undefined>(items:Video[],setItems:React.Dispatch<React.SetStateAction<S>>)=>items.filter(x=>!x.cover).slice(0,60).forEach(video=>{api<Video>(`/sources/${video.sourceKey}/videos/${video.id}`).then(detail=>{if(detail.cover)setItems(current=>(current?current.map(x=>x.id===video.id?{...x,cover:detail.cover,desc:detail.desc||x.desc}:x):current) as S)}).catch(()=>{})});
const json=(data:any):RequestInit=>({method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});
const lineLabel=(name:string)=>{try{return JSON.parse(localStorage.getItem('tvbox.lineAliases')||'{}')[name]||name}catch{return name}};
const timeAgo=(value:string)=>{const s=Math.max(1,Math.floor((Date.now()-new Date(value).getTime())/1000));if(s<60)return '刚刚';if(s<3600)return `${Math.floor(s/60)} 分钟前`;if(s<86400)return `${Math.floor(s/3600)} 小时前`;return `${Math.floor(s/86400)} 天前`};
function Avatar({user,large=false}:{user?:Partial<User>;large?:boolean}){return <span className={`avatar ${large?'avatar-large':''}`}><img src={user?.avatarUrl||'/images/default-avatar.svg'} alt="用户头像" onError={e=>{e.currentTarget.src='/images/default-avatar.svg'}}/></span>}
function Spinner({label='正在加载'}:{label?:string}){return <div className="state-box"><span className="spinner"/><p>{label}</p></div>}
function Empty({title,detail}:{title:string;detail?:string}){return <div className="empty-state"><b>◇</b><h3>{title}</h3>{detail&&<p>{detail}</p>}</div>}
function Progress({value}:{value:number}){return <span className="progress"><i style={{width:`${Math.min(100,Math.max(0,value))}%`}}/></span>}
function Poster({src,title}:{src?:string;title:string}){const [failed,setFailed]=useState(false);useEffect(()=>setFailed(false),[src]);return failed||!src?<span className="poster-fallback">{title.slice(0,1)}</span>:<img loading="eager" decoding="async" fetchPriority="high" src={src} alt={title} onError={()=>setFailed(true)}/>}
function MovieCard({video,progress}:{video:Video;progress?:number}){return <CinemaCard video={video} progress={progress}/>;}
function Page({title,eyebrow,children}:{title:string;eyebrow?:string;children:React.ReactNode}){return <div className="content-page"><div className="page-heading"><small>{eyebrow}</small><h1>{title}</h1></div>{children}</div>}
function Guard({user,admin=false,children}:{user:User|null|undefined;admin?:boolean;children:React.ReactNode}){const location=useLocation();if(user===undefined)return <Spinner label="正在验证登录状态"/>;if(!user)return <Navigate to="/login" replace/>;if(admin&&user.role!=='admin')return <Navigate to="/membership" replace/>;const permission=pagePermission(location.pathname);if(!admin&&user.role!=='admin'&&permission&&!user.permissions.includes(permission))return <main className="content-page member-page"><h1>当前等级暂不可访问</h1><p className="member-muted">请查看会员权益，或联系管理员调整授权。</p><Link to="/membership">查看会员与积分 →</Link></main>;return <>{children}</>}

function Login({settings}:{settings:Settings}){const [username,setUsername]=useState('');const [password,setPassword]=useState('');const [busy,setBusy]=useState(false);const [message,setMessage]=useState('');const submit=async(e:React.FormEvent)=>{e.preventDefault();setBusy(true);setMessage('');try{await api('/auth/login',json({username,password}));location.href='/'}catch(error:any){setMessage(error.message)}finally{setBusy(false)}};return <div className="login-screen"><div className="login-backdrop"/><form className="login-panel" onSubmit={submit}><Link className="login-logo" to="/"><img src={settings.logoUrl||'/images/dabiao-logo.svg'} alt={settings.siteName||'大彪TV'}/></Link><h1>欢迎回来</h1><p>登录后继续你的观影旅程</p><label>账号<input required value={username} onChange={e=>setUsername(e.target.value)} autoComplete="username"/></label><label>密码<input required type="password" value={password} onChange={e=>setPassword(e.target.value)} autoComplete="current-password"/></label><div className="session-note">安全登录状态将自动保持 30 天</div><button className="primary wide" disabled={busy}>{busy?'正在登录…':'登录'}</button>{settings.allowRegister==='true'&&<p><Link to="/register">注册新账号</Link></p>}{message&&<p className="form-error">{message}</p>}</form></div>}
function Install({settings,status}:{settings:Settings;status:any}){return <InstallWizard settings={settings} status={status}/>}
function UserMenu({user,onLogout}:{user:User;onLogout:()=>void}){const [open,setOpen]=useState(false);const ref=useRef<HTMLDivElement>(null);useEffect(()=>{const click=(e:MouseEvent)=>{if(!ref.current?.contains(e.target as Node))setOpen(false)};const key=(e:KeyboardEvent)=>{if(e.key==='Escape')setOpen(false)};document.addEventListener('mousedown',click);document.addEventListener('keydown',key);return()=>{document.removeEventListener('mousedown',click);document.removeEventListener('keydown',key)}},[]);return <div className="user-menu" ref={ref}><button aria-label="打开用户菜单" aria-expanded={open} onClick={()=>setOpen(!open)}><Avatar user={user}/><span>⌄</span></button>{open&&<div className="user-dropdown"><div className="user-card"><Avatar user={user}/><div><b>{user.displayName||user.username}</b><small>{user.membership?.name||'普通用户'}</small></div></div><Link to="/membership" onClick={()=>setOpen(false)}>会员与积分 · {user.points||0}积分</Link><Link to="/profile" onClick={()=>setOpen(false)}>个人中心</Link><Link to="/profile?tab=continue" onClick={()=>setOpen(false)}>继续观看</Link><Link to="/history" onClick={()=>setOpen(false)}>观看历史</Link><Link to="/favorites" onClick={()=>setOpen(false)}>我的收藏</Link>{user.role==='admin'&&<Link to="/admin" onClick={()=>setOpen(false)}>管理后台</Link>}<button className="logout" onClick={onLogout}>退出登录</button></div>}</div>}
function Header({user,settings,onLogout}:{user:User|null;settings:Settings;onLogout:()=>void}){const nav=useNavigate();const [query,setQuery]=useState('');const [scrolled,setScrolled]=useState(false);useEffect(()=>{const f=()=>setScrolled(Math.max(window.scrollY,document.documentElement.scrollTop,document.body.scrollTop)>18);f();addEventListener('scroll',f,true);return()=>removeEventListener('scroll',f,true)},[]);return <><header className={`site-header ${scrolled?'scrolled':''}`}><Link className="brand" to="/"><img src={settings.logoUrl||'/images/dabiao-logo.svg'} alt={settings.siteName||'大彪TV'} onError={e=>{e.currentTarget.src='/images/dabiao-logo.svg'}}/></Link><MainNavigation user={user}/><form className="header-search" onSubmit={e=>{e.preventDefault();if(query.trim())nav('/search?q='+encodeURIComponent(query.trim()))}}><span><Icon name="search" size={17}/></span><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="搜索影视、演员、导演"/></form><div className="header-icons"><Link className="cinema-icon-link" aria-label="观看历史" to="/history"><Icon name="clock"/></Link><Link className="cinema-icon-link" aria-label="收藏" to="/favorites"><Icon name="bookmark"/></Link>{user?<UserMenu user={user} onLogout={onLogout}/>:<Link className="login-link" to="/login">登录</Link>}</div></header><MainNavigation mobile docked={scrolled} user={user}/><nav className="mobile-nav"><Link to="/">⌂<span>首页</span></Link><Link to="/search">⌕<span>搜索</span></Link><Link to="/favorites">♡<span>收藏</span></Link><Link to="/history">◷<span>历史</span></Link><Link to="/profile">○<span>我的</span></Link></nav></>}

function Home({settings,user}:{settings:Settings;user?:User|null}){return <CinemaHome settings={settings} permissions={user?.permissions}/>;}
function Sources(){const [items,setItems]=useState<any[]>();useEffect(()=>{api<any[]>('/library').then(setItems)},[]);if(!items)return <Spinner/>;return <Page title="片库" eyebrow="LIBRARY"><div className="library-note">本地采集内容和已配置的远程 TVBox 播放源都会显示在这里；远程源打开后实时读取内容。</div><div className="source-grid">{items.map(x=><Link className="source-tile" to={`/source/${x.key}`} key={x.key}><span>◈</span><div><h3>{x.name}</h3><p>{x.type==='local'?'本地资源': '远程资源'} · {x._count?.videos||0} 部已采集</p></div><b>→</b></Link>)}</div></Page>}
function Source(){
  const {key}=useParams(),pagination=useVideoPagination(),{page,pageSize}=pagination;
  const [items,setItems]=useState<Video[]>([]),[cats,setCats]=useState<string[]>([]),[filters,setFilters]=useState<any>({years:[],areas:[],languages:[]});
  const [category,setCategory]=useState(''),[year,setYear]=useState(''),[area,setArea]=useState(''),[language,setLanguage]=useState('');
  const [total,setTotal]=useState<number|null>(null),[hasMore,setHasMore]=useState(false),[loading,setLoading]=useState(true),[error,setError]=useState(''),[paginationNote,setPaginationNote]=useState('');
  useEffect(()=>{const controller=new AbortController();setCats([]);setFilters({years:[],areas:[],languages:[]});Promise.all([api<string[]>('/sources/'+key+'/categories',{signal:controller.signal}),api('/sources/'+key+'/filters',{signal:controller.signal})]).then(([c,f])=>{if(!controller.signal.aborted){setCats(c);setFilters(f)}}).catch(()=>{});return()=>controller.abort()},[key]);
  useEffect(()=>{const controller=new AbortController();setLoading(true);setError('');setItems([]);const query=new URLSearchParams({page:String(page),pageSize:String(pageSize)});
    for(const [name,value] of Object.entries({category,year,area,language}))if(value)query.set(name,value);
    api<any>('/sources/'+encodeURIComponent(key||'')+'/videos?'+query,{signal:controller.signal}).then(data=>{if(controller.signal.aborted)return;setItems(data.items);setTotal(data.total);setPaginationNote(data.paginationWarning||'');setHasMore(data.hasMore??page*pageSize<data.total)}).catch(error=>{if(error.name!=='AbortError')setError(error.message)}).finally(()=>{if(!controller.signal.aborted)setLoading(false)});return()=>controller.abort();
  },[key,page,pageSize,category,year,area,language]);
  const change=(setter:(value:string)=>void,value:string)=>{setter(value);pagination.turnPage(1)};
  const pager=<nav className="browse-pager" aria-label="源片库分页"><button disabled={loading||page<=1} onClick={()=>pagination.turnPage(page-1)}>← 上一页</button><span>第 {page}{total!==null?' / '+Math.max(1,Math.ceil(total/pageSize)):''} 页</span><button disabled={loading||!hasMore} onClick={()=>pagination.turnPage(page+1)}>下一页 →</button></nav>;
  return <Page title="内容库" eyebrow={String(key||'SOURCE')}><div className="filter-bar"><select aria-label="源片库分类" value={category} onChange={event=>change(setCategory,event.target.value)}><option value="">全部类型</option>{cats.map(name=><option key={name}>{name}</option>)}</select><select aria-label="源片库年份" value={year} onChange={event=>change(setYear,event.target.value)}><option value="">全部年份</option>{filters.years.map((value:any)=><option key={value}>{value}</option>)}</select><select aria-label="源片库地区" value={area} onChange={event=>change(setArea,event.target.value)}><option value="">全部地区</option>{filters.areas.map((value:any)=><option key={value}>{value}</option>)}</select><select aria-label="源片库语言" value={language} onChange={event=>change(setLanguage,event.target.value)}><option value="">全部语言</option>{filters.languages.map((value:any)=><option key={value}>{value}</option>)}</select></div><div className="video-list-toolbar"><span className="video-list-note">本页 {items.length} 部</span><PageSizeControl pagination={pagination}/></div>{pager}{error?<p role="alert" className="browse-error">{error}</p>:loading?<Spinner label="正在读取内容"/>:items.length?<div className="movie-grid video-list-grid">{items.map(video=><MovieCard video={video} key={video.id}/>)}</div>:<Empty title="这个分类暂时没有内容"/>}{!!items.length&&pager}{paginationNote&&<p className="video-list-note">{paginationNote}</p>}</Page>;
}
function Detail(){const {sourceKey,videoId}=useParams();const [video,setVideo]=useState<Video>();const [favorite,setFavorite]=useState(false);const [line,setLine]=useState('');const [reverse,setReverse]=useEpisodeOrder();const [detailError,setDetailError]=useState('');const detailLocation=useLocation();useEffect(()=>{let cancelled=false;setVideo(undefined);setDetailError('');performance.mark('detail-request-start');api<Video>(`/sources/${sourceKey}/videos/${videoId}`).then(v=>{if(cancelled)return;setVideo(v);setLine(matchingEpisode(v.episodes||[])?.lineName||'默认线路');performance.mark('detail-request-end');if(import.meta.env.DEV)console.info('[大彪TV performance] detailFetchTime',performance.measure('detail-fetch','detail-request-start','detail-request-end').duration.toFixed(1)+'ms');const url=v.episodes?.[0]?.url;try{if(url){const origin=new URL(url).origin;if(!document.querySelector(`link[data-media-origin="${origin}"]`)){const link=document.createElement('link');link.rel='preconnect';link.href=origin;link.crossOrigin='anonymous';link.dataset.mediaOrigin=origin;document.head.appendChild(link)}}}catch{}}).catch(e=>{if(!cancelled)setDetailError(e.message)});api<any[]>('/favorites').then(xs=>{if(!cancelled)setFavorite(xs.some(x=>x.videoId===videoId))}).catch(()=>{});return()=>{cancelled=true}},[sourceKey,videoId]);if(detailError)return <Page title="无法加载影片"><p role="alert">{detailError}</p></Page>;if(!video)return <Spinner label="正在读取影片详情"/>;const available=video.episodes||[];const playable=available.some(isDirectEpisode)?available.filter(isDirectEpisode):available;const lines=[...new Set(playable.map(x=>x.lineName||'默认线路'))];const episodes=(video.episodes||[]).filter(x=>(x.lineName||'默认线路')===line).sort((a,b)=>a.sortOrder-b.sortOrder);const toggle=async()=>{if(favorite){const xs=await api<any[]>('/favorites');const row=xs.find(x=>x.videoId===videoId);if(row)await api(`/favorites/${row.id}`,{method:'DELETE'});setFavorite(false)}else{await api('/favorites',json({sourceKey,videoId,title:video.title,cover:video.cover}));setFavorite(true)}};return <div className="detail-page"><div className="detail-backdrop" style={{backgroundImage:`linear-gradient(90deg,#0b0b0f 5%,rgba(11,11,15,.82) 48%,rgba(11,11,15,.36)),url(${video.cover})`}}/><Link className="back-link" to={`/source/${sourceKey}`}>← 返回片库</Link><div className="detail-content"><div className="detail-poster"><Poster src={video.cover} title={video.title}/></div><div className="detail-info"><small>{video.category} · {video.year||'年份未知'} · {video.area||'地区未知'}</small><h1>{video.title}</h1><RatingBadge video={video}/><p>{video.desc||'暂无剧情简介'}</p><div className="detail-meta"><span><b>导演</b>{video.director||'未知'}</span><span><b>主演</b>{video.actors||'未知'}</span><span><b>语言</b>{video.language||'未知'}</span></div><div className="detail-actions">{episodes[0]&&<Link className="play-button" to={`/player/${sourceKey}/${videoId}/${episodes[0].id}`}>▶ 立即播放</Link>}<button className="info-button" onClick={toggle}>{favorite?'♥ 已收藏':'♡ 加入收藏'}</button></div><div className="episode-panel"><PlaybackSources sourceKey={sourceKey||''} videoId={videoId||''} video={video}/>{detailLocation.search.includes('chooseEpisode=1')&&<p className="source-switch-note">该源未找到对应集，请重新选集。</p>}<div className="episode-heading"><h2>选集</h2><EpisodeOrder reverse={reverse} onChange={setReverse}/></div><div className="line-tabs" aria-label="源内线路">{lines.map(x=><button className={line===x?'active':''} onClick={()=>setLine(x)} key={x}>{video.sourceName||sourceKey}{lines.length>1?` · ${lineLabel(x)===x?'线路 '+(lines.indexOf(x)+1):lineLabel(x)}`:''}</button>)}</div><div className="episode-grid">{episodeDisplayOrder(episodes,reverse).map(e=><Link to={`/player/${sourceKey}/${videoId}/${e.id}`} key={e.id}>{e.name}</Link>)}</div></div></div></div></div>}

function DanmakuLayer({items,current}:{items:any[];current:number}){return <div className="danmaku-layer">{items.filter(x=>Math.abs(x.videoTime-current)<6).slice(-18).map((x,i)=><span key={`${x.id}-${i}`} style={{top:`${8+(i%7)*11}%`,animationDelay:`${(i%5)*-.5}s`}}>{x.content}</span>)}</div>}
function Player({settings}:{settings:Settings}){const {sourceKey,videoId,episodeId}=useParams();const nav=useNavigate();const [reverse,setReverse]=useEpisodeOrder();const videoRef=useRef<HTMLVideoElement>(null);const [video,setVideo]=useState<Video>();const [episode,setEpisode]=useState<Episode>();const [line,setLine]=useState('');const [current,setCurrent]=useState(0);const [danmaku,setDanmaku]=useState<any[]>([]);const [danmakuOn,setDanmakuOn]=useState(()=>localStorage.getItem('danmaku')!=='off');const [text,setText]=useState('');const [stage,setStage]=useState('正在获取播放线路…');const playStarted=useRef(performance.now());useEffect(()=>{let cancelled=false;setEpisode(undefined);setStage('正在获取播放线路…');api<Video>(`/sources/${sourceKey}/videos/${videoId}`).then(v=>{if(cancelled)return;setVideo(v);const e=v.episodes?.find(x=>x.id===episodeId);if(e&&!isDirectEpisode(e)){const direct=matchingEpisode(v.episodes||[],e);if(direct&&direct.id!==e.id&&isDirectEpisode(direct)){nav(`/player/${sourceKey}/${videoId}/${direct.id}`,{replace:true});return}}setEpisode(e);setLine(e?.lineName||'');setStage('正在连接视频源…');if(import.meta.env.DEV)console.info('[大彪TV performance] playUrlResolveTime',(performance.now()-playStarted.current).toFixed(1)+'ms')}).catch(()=>{if(!cancelled)setStage('读取播放源失败，请返回详情重新选择')});return()=>{cancelled=true}},[sourceKey,videoId,episodeId]);useEffect(()=>{if(episode)api<any[]>(`/danmaku?episodeId=${encodeURIComponent(episode.id)}`).then(setDanmaku)},[episode]);useEffect(()=>{const el=videoRef.current;if(!el)return;if(!episode){el.pause();el.removeAttribute('src');el.load();return}let h:Hls|undefined;if(episode.type==='m3u8'&&Hls.isSupported()){h=new Hls({manifestLoadingTimeOut:8000,levelLoadingTimeOut:8000,fragLoadingTimeOut:12000,maxBufferLength:30});h.loadSource(episode.url);h.attachMedia(el)}else el.src=episode.url;const playing=()=>{setStage('');if(import.meta.env.DEV)console.info('[大彪TV performance] playingTime',(performance.now()-playStarted.current).toFixed(1)+'ms')};const waiting=()=>setStage('正在缓冲视频…');const error=()=>{setStage('当前线路响应较慢，请尝试切换线路');api('/playback-errors',json({sourceKey,videoId,episodeId,errorType:'media',errorMessage:el.error?.message||'播放失败'})).catch(()=>{})};el.addEventListener('playing',playing);el.addEventListener('canplay',playing);el.addEventListener('waiting',waiting);el.addEventListener('error',error);return()=>{h?.destroy();el.removeEventListener('playing',playing);el.removeEventListener('canplay',playing);el.removeEventListener('waiting',waiting);el.removeEventListener('error',error)}},[episode]);const save=()=>{const el=videoRef.current;if(!el||!video||!episode||video.id!==videoId||episode.id!==episodeId||!Number.isFinite(el.duration))return;api('/history',json({sourceKey,videoId,episodeId,title:video.title,cover:video.cover,episodeName:episode.name,progress:el.currentTime,duration:el.duration,completed:el.currentTime/el.duration>.92})).catch(()=>{})};useEffect(()=>{const timer=setInterval(save,20000);const leave=()=>save();addEventListener('beforeunload',leave);return()=>{clearInterval(timer);removeEventListener('beforeunload',leave);save()}},[video,episode]);const all=video?.episodes||[];const playable=all.some(isDirectEpisode)?all.filter(isDirectEpisode):all;const lines=[...new Set(playable.map(x=>x.lineName))];const episodes=all.filter(x=>x.lineName===line).sort((a,b)=>a.sortOrder-b.sortOrder);const index=episodes.findIndex(x=>x.id===episodeId);const switchLine=(next:string)=>{const target=matchingEpisode(all.filter(x=>x.lineName===next),episode)||all.find(x=>x.lineName===next);if(target)nav(`/player/${sourceKey}/${videoId}/${target.id}`)};const send=async()=>{if(!text.trim()||!episode)return;const row=await api('/danmaku',json({sourceKey,videoId,episodeId:episode.id,content:text,videoTime:videoRef.current?.currentTime||0}));setDanmaku([...danmaku,row]);setText('')};return <div className="watch-page"><div className="watch-top"><Link to={`/detail/${sourceKey}/${videoId}`}>← 返回详情</Link><span>{video?.title} {episode?.name&&`· ${episode.name}`}</span></div><div className="video-shell"><video ref={videoRef} controls autoPlay playsInline preload="metadata" onTimeUpdate={e=>setCurrent(e.currentTarget.currentTime)} onPause={save}/>{stage&&<PlaybackLoading stage={stage}/>}{danmakuOn&&settings.danmakuEnabled!=='false'&&<DanmakuLayer items={danmaku.filter(x=>!x.simulated||settings.simulatedDanmakuEnabled!=='false')} current={current}/>}</div><PlaybackSources mode="player" sourceKey={sourceKey||''} videoId={videoId||''} video={video} currentEpisode={episode} onBeforeSwitch={save}/><div className="watch-toolbar"><div className="line-tabs"><b>源内线路</b>{lines.map(x=><button className={line===x?'active':''} onClick={()=>switchLine(x)} key={x}>{video?.sourceName||sourceKey}{lines.length>1?` · ${lineLabel(x)===x?'线路 '+(lines.indexOf(x)+1):lineLabel(x)}`:''}</button>)}</div><button onClick={()=>{const n=!danmakuOn;setDanmakuOn(n);localStorage.setItem('danmaku',n?'on':'off')}}>{danmakuOn?'弹幕开':'弹幕关'}</button></div>{danmakuOn&&settings.realDanmakuEnabled!=='false'&&<div className="danmaku-send"><input value={text} maxLength={80} onChange={e=>setText(e.target.value)} onKeyDown={e=>e.key==='Enter'&&send()} placeholder="发一条友善的弹幕"/><button onClick={send}>发送</button></div>}<div className="watch-info"><div><h2>{video?.title||'正在加载'}</h2><p>{video?.desc||'暂无简介'}</p></div><div className="episode-nav">{episodes[index-1]?<Link to={`/player/${sourceKey}/${videoId}/${episodes[index-1].id}`}>← 上一集</Link>:<span/>}{episodes[index+1]&&<Link to={`/player/${sourceKey}/${videoId}/${episodes[index+1].id}`}>下一集 →</Link>}</div></div><div className="episode-heading player-episode-heading"><h2>选集</h2><EpisodeOrder reverse={reverse} onChange={setReverse}/></div><div className="episode-grid player-episode-grid">{episodeDisplayOrder(episodes,reverse).map(x=><Link className={x.id===episodeId?'active':''} to={`/player/${sourceKey}/${videoId}/${x.id}`} key={x.id}>{x.name}</Link>)}</div></div>}

function CategoryBrowse({category}:{category:string}){return <BrowsePage key={category} category={category} renderVideo={video=><MovieCard video={video}/>}/>;}
function CategoryRoute(){const {category='电影'}=useParams();return mainCategories.includes(category)?<CategoryBrowse category={category}/>:<Navigate to="/category/电影" replace/>;}
function Search(){
  const location=useLocation(),nav=useNavigate();
  const initial=new URLSearchParams(location.search).get('q')||'';
  const [query,setQuery]=useState(initial),[items,setItems]=useState<Video[]>(),[error,setError]=useState('');
  useEffect(()=>{let cancelled=false;setQuery(initial);setError('');if(!initial){setItems([]);return}setItems(undefined);
    api<Video[]>('/search?q='+encodeURIComponent(initial)).then(next=>{if(cancelled)return;setItems(next);hydrateMissingCovers(next,setItems)}).catch(e=>{if(!cancelled){setError(e.message);setItems([])}});
    return()=>{cancelled=true};
  },[initial]);
  return <Page title="全站搜索" eyebrow="DISCOVER"><form className="big-search" onSubmit={e=>{e.preventDefault();nav('/search?q='+encodeURIComponent(query.trim()))}}><span><Icon name="search" size={22}/></span><input autoFocus value={query} onChange={e=>setQuery(e.target.value)} placeholder="搜索影视名称"/><button>搜索</button></form>
    <p className="search-source-note">搜索后台已启用且允许搜索的全部数据源。同名影片合并展示，进入详情后可按源名切换播放源。{new URLSearchParams(location.search).get('year')&&` 来自 TMDB 的目标年份：${new URLSearchParams(location.search).get('year')}，请核对版本后播放。`}</p>
    {error?<p role="alert">{error}</p>:items===undefined?<Spinner label="正在搜索各数据源…"/>:items.length?<div className="movie-grid">{items.map(v=><MovieCard video={v} key={v.sourceKey+':'+v.id}/>)}</div>:<Empty title={initial?'没有找到相关内容':'输入关键词开始搜索'} detail={initial?'换个片名，或在后台检查数据源的搜索开关':''}/>}</Page>;
}
function Favorites(){const [items,setItems]=useState<any[]>();const load=()=>api<any[]>('/favorites').then(setItems);useEffect(()=>{void load()},[]);return <Page title="我的收藏" eyebrow="MY LIST">{items===undefined?<Spinner/>:items.length?<div className="movie-grid">{items.map(x=><div className="library-item" key={x.id}><MovieCard video={{...x,id:x.videoId}}/><button onClick={async()=>{await api(`/favorites/${x.id}`,{method:'DELETE'});load()}}>移除</button></div>)}</div>:<Empty title="收藏夹还是空的" detail="在影片详情页点击加入收藏"/>}</Page>}
function History(){const [items,setItems]=useState<any[]>();const [confirmClear,setConfirmClear]=useState(false);const load=()=>api<any[]>('/history').then(setItems);useEffect(()=>{void load()},[]);return <Page title="观看历史" eyebrow="WATCH HISTORY"><div className="page-actions">{!!items?.length&&<button onClick={()=>setConfirmClear(true)}>清空历史</button>}</div>{items===undefined?<Spinner/>:items.length?<div className="history-list">{items.map(x=><div key={x.id}><Link to={`/player/${x.sourceKey}/${x.videoId}/${x.episodeId}`}><div className="history-cover"><Poster src={x.cover} title={x.title}/></div><div><h3>{x.title}</h3><p>{x.episodeName||'继续观看'} · {timeAgo(x.updatedAt)}</p><Progress value={x.duration?x.progress/x.duration*100:0}/></div></Link><button onClick={async()=>{await api(`/history/${x.id}`,{method:'DELETE'});load()}}>×</button></div>)}</div>:<Empty title="暂无观看记录"/>}{confirmClear&&<div className="modal-backdrop" onClick={()=>setConfirmClear(false)}><div className="confirm-dialog" onClick={e=>e.stopPropagation()}><h3>清空观看历史？</h3><p>这会删除你的全部观看记录，且无法撤销。</p><div><button onClick={()=>setConfirmClear(false)}>取消</button><button className="danger-action" onClick={async()=>{await api('/history',{method:'DELETE'});setConfirmClear(false);load()}}>确认清空</button></div></div></div>}</Page>}
function Profile({user}:{user:User}){const tab=new URLSearchParams(useLocation().search).get('tab')||'profile';const [profile,setProfile]=useState<any>();const [form,setForm]=useState({displayName:'',avatarUrl:''});const [password,setPassword]=useState({currentPassword:'',newPassword:''});const [message,setMessage]=useState('');useEffect(()=>{api('/profile').then(x=>{setProfile(x);setForm({displayName:x.displayName,avatarUrl:x.avatarUrl})})},[]);if(!profile)return <Spinner/>;return <div className="profile-layout"><aside><Avatar user={{...user,...form}} large/><h2>{form.displayName||user.username}</h2><p>{user.role==='admin'?'管理员':'普通用户'}</p><Link to="/membership">会员与积分 · {user.points}积分</Link><Link className={tab==='profile'?'active':''} to="/profile">个人资料</Link><Link className={tab==='continue'?'active':''} to="/profile?tab=continue">继续观看</Link><Link to="/history">观看历史</Link><Link to="/favorites">我的收藏</Link><Link className={tab==='account'?'active':''} to="/profile?tab=account">账号设置</Link></aside><main>{tab==='continue'?<><h1>继续观看</h1><div className="history-list">{profile.recent.map((x:any)=><div key={x.id}><Link to={`/player/${x.sourceKey}/${x.videoId}/${x.episodeId}`}><div className="history-cover"><Poster src={x.cover} title={x.title}/></div><div><h3>{x.title}</h3><p>{x.episodeName}</p><Progress value={x.duration?x.progress/x.duration*100:0}/></div></Link></div>)}</div></>:tab==='account'?<><h1>账号设置</h1><div className="profile-form"><label>当前密码<input type="password" value={password.currentPassword} onChange={e=>setPassword({...password,currentPassword:e.target.value})}/></label><label>新密码<input type="password" value={password.newPassword} onChange={e=>setPassword({...password,newPassword:e.target.value})}/></label><button className="primary" onClick={async()=>{await api('/profile/password',json(password));setMessage('密码修改成功');setPassword({currentPassword:'',newPassword:''})}}>修改密码</button></div></>:<><h1>个人资料</h1><div className="profile-stats"><span><b>{profile.stats.historyCount}</b>观看记录</span><span><b>{profile.stats.favorites}</b>收藏</span><span><b>{Math.round(profile.stats.watchSeconds/3600)}</b>观看小时</span></div><div className="profile-form"><label>会员号<input value={user.memberNo||''} readOnly/></label><label>用户名<input value={profile.username} disabled/></label><label>昵称<input value={form.displayName} onChange={e=>setForm({...form,displayName:e.target.value})}/></label><label>头像地址<input value={form.avatarUrl} onChange={e=>setForm({...form,avatarUrl:e.target.value})}/></label><button className="primary" onClick={async()=>{await api('/profile',{...json(form),method:'PUT'});setMessage('个人资料已保存')}}>保存资料</button></div></>}{message&&<p className="success-message">{message}</p>}</main></div>}

const adminLinks=[['/admin','仪表盘','▦'],['/admin/settings','网站设置','⚙'],['/admin/updates','系统更新','↻'],['/admin/resource-center','资源中心','◈'],['/admin/sources','数据源管理','◉'],['/admin/collection','本地采集','⇩'],['/admin/categories','分类管理','#'],['/admin/videos','视频管理','▤'],['/admin/editor','源配置','⌘'],['/admin/users','用户管理','♙'],['/admin/membership','会员与积分','♔'],['/admin/history','观看统计','◷'],['/admin/danmaku','弹幕管理','≋'],['/admin/errors','播放错误','!'],['/admin/logs','系统日志','☰']];
function CategoryManager(){const [items,setItems]=useState<any[]>(),[name,setName]=useState(''),[message,setMessage]=useState('');const load=()=>api<any[]>('/admin/category-stats').then(setItems);useEffect(()=>{void load()},[]);const add=async()=>{const n=name.trim();if(!n)return;const all=(items||[]).map(x=>x.name);await api('/admin/categories',json({categories:[...new Set([...all,n])]}));setName('');setMessage('分类已添加');load()};const rename=async(old:string)=>{const n=window.prompt('修改分类名称',old)?.trim();if(n&&n!==old){await api(`/admin/categories/${encodeURIComponent(old)}`,{...json({name:n}),method:'PUT'});setMessage('分类已修改');load()}};const remove=async(old:string)=>{if(!window.confirm(`确定删除“${old}”？视频将移到未分类`))return;await api(`/admin/categories/${encodeURIComponent(old)}`,{method:'DELETE',headers:{'Content-Type':'application/json'},body:'{}'});setMessage('分类已删除');load()};return <AdminFrame title="分类管理"><div className="manager-intro"><b>本站分类</b><p>统一管理分类名称，修改后会同步更新绑定和本地视频。</p></div><div className="manager-add"><input value={name} onChange={e=>setName(e.target.value)} placeholder="输入新分类名称"/><button className="primary" onClick={()=>void add()}>添加分类</button></div>{message&&<p className="success-message">{message}</p>}<div className="category-grid">{!items?<Spinner/>:items.map(x=><div className="category-card" key={x.name}><div><b>{x.name}</b><small>{x.videoCount} 部本地视频</small></div><span><button onClick={()=>void rename(x.name)}>改名</button><button className="danger-text" onClick={()=>void remove(x.name)}>删除</button></span></div>)}</div></AdminFrame>}
function VideoManager(){const [items,setItems]=useState<any[]>(),[sources,setSources]=useState<any[]>([]),[categories,setCategories]=useState<any[]>([]),[selected,setSelected]=useState<string[]>([]),[q,setQ]=useState(''),[sourceKey,setSourceKey]=useState(''),[category,setCategory]=useState(''),[message,setMessage]=useState('');const load=()=>api<any>(`/admin/videos?page=1&pageSize=100&q=${encodeURIComponent(q)}&sourceKey=${encodeURIComponent(sourceKey)}&category=${encodeURIComponent(category)}`).then(x=>{setItems(x.items);setSelected([])});useEffect(()=>{void load();api<any[]>('/admin/sources').then(setSources);api<any[]>('/admin/category-stats').then(setCategories)},[]);const bulk=async(action:string)=>{if(!selected.length)return setMessage('请先选择视频');if(action==='delete'&&!window.confirm('确定删除选中的本地视频？'))return;await api('/admin/videos/batch',json({ids:selected,action,category}));setMessage('批量操作已完成');load()};return <AdminFrame title="视频管理"><div className="manager-intro"><b>本地视频库</b><p>只管理已采集到本机的内容，可批量显示、隐藏、推荐、改分类或删除。</p></div><div className="video-filters"><input placeholder="搜索视频名称" value={q} onChange={e=>setQ(e.target.value)} onKeyDown={e=>e.key==='Enter'&&void load()}/><select value={sourceKey} onChange={e=>setSourceKey(e.target.value)}><option value="">全部数据源</option>{sources.map(x=><option key={x.key} value={x.key}>{x.name}</option>)}</select><select value={category} onChange={e=>setCategory(e.target.value)}><option value="">全部分类</option>{categories.map(x=><option key={x.name} value={x.name}>{x.name}</option>)}</select><button onClick={()=>void load()}>筛选</button></div><div className="video-bulk"><label><input type="checkbox" checked={Boolean(items?.length&&selected.length===items.length)} onChange={e=>setSelected(e.target.checked?(items||[]).map(x=>x.id):[])}/> 全选</label><button onClick={()=>void bulk('show')}>批量显示</button><button onClick={()=>void bulk('hide')}>批量隐藏</button><button onClick={()=>void bulk('feature')}>设为推荐</button><button onClick={()=>void bulk('unfeature')}>取消推荐</button><select onChange={e=>{setCategory(e.target.value);if(e.target.value)void bulk('category')}} value=""><option value="">批量改分类</option>{categories.map(x=><option key={x.name} value={x.name}>{x.name}</option>)}</select><button className="danger-text" onClick={()=>void bulk('delete')}>批量删除</button></div>{message&&<p className="success-message">{message}</p>}{!items?<Spinner/>:<div className="video-table"><div className="video-table-head"><span></span><span>视频</span><span>数据源</span><span>分类</span><span>状态</span></div>{items.map(x=><div className="video-table-row" key={x.id}><input type="checkbox" checked={selected.includes(x.id)} onChange={e=>setSelected(e.target.checked?[...selected,x.id]:selected.filter(id=>id!==x.id))}/><span className="video-title"><img src={x.cover||'/images/dabiao-icon.svg'}/><b>{x.title}</b></span><span>{x.source?.name||x.sourceKey}</span><span>{x.category||'未分类'}</span><span>{x.visible===false?'已隐藏':'显示中'}{x.featured?' · 推荐':''}</span></div>)}</div>}</AdminFrame>}
function SchedulePanel(){const [cfg,setCfg]=useState<any>({enabled:false,intervalMinutes:1440,nextAt:null}),[message,setMessage]=useState('');useEffect(()=>{api('/admin/collection-schedule').then(setCfg)},[]);const save=async()=>{const x=await api('/admin/collection-schedule',{...json(cfg),method:'PUT'});setCfg(x);setMessage('自动采集间隔已保存')};const mins=Number(cfg.intervalMinutes)||1440;const label=mins<60?`每 ${mins} 分钟`:mins%60?`每 ${Math.floor(mins/60)} 小时 ${mins%60} 分钟`:`每 ${mins/60} 小时`;return <section className="schedule-panel"><div><b>自动采集间隔</b><p>按已保存的分类绑定，自动采集所有启用数据源。</p></div><label><input type="checkbox" checked={cfg.enabled} onChange={e=>setCfg({...cfg,enabled:e.target.checked})}/> 开启</label><select value={cfg.intervalMinutes} onChange={e=>setCfg({...cfg,intervalMinutes:Number(e.target.value)})}><option value="30">每 30 分钟</option><option value="60">每 1 小时</option><option value="180">每 3 小时</option><option value="360">每 6 小时</option><option value="720">每 12 小时</option><option value="1440">每 24 小时</option><option value="2880">每 2 天</option><option value="10080">每 7 天</option></select><button onClick={()=>void save()}>保存</button><small>{cfg.enabled?(cfg.nextAt?`下一次采集：${new Date(cfg.nextAt).toLocaleString()}（${label}）`:`已开启（${label}）`):'自动采集未开启'}</small>{message&&<small>{message}</small>}</section>}
function AdminFrame({title,children}:{title:string;children:React.ReactNode}){return <AdminShell title={title} links={adminLinks}>{children}</AdminShell>}
function AdminDashboard(){const [data,setData]=useState<any>();useEffect(()=>{api('/admin/dashboard').then(setData)},[]);if(!data)return <AdminFrame title="仪表盘"><Spinner/></AdminFrame>;const max=Math.max(1,...data.trend.map((x:any)=>x.count));return <AdminFrame title="仪表盘"><div className="admin-stats">{[['平台用户',data.users],['今日新增',data.newUsers],['今日活跃',data.activeUsers],['今日播放',data.todayPlays],['总观看记录',data.historyTotal],['有效数据源',`${data.healthy}/${data.sources}`],['今日播放错误',data.errors]].map(([a,b])=><div key={String(a)}><span>{a}</span><b>{b}</b></div>)}</div><div className="dashboard-grid"><article className="chart-card"><h3>最近 7 天播放趋势</h3><div className="bar-chart">{data.trend.map((x:any)=><div key={x.date}><i style={{height:`${Math.max(5,x.count/max*100)}%`}}/><span>{x.date.slice(5)}</span><b>{x.count}</b></div>)}</div></article><article><h3>热门搜索</h3><ol>{data.topSearches.map((x:any)=><li key={x.keyword}><span>{x.keyword}</span><b>{x._count.keyword}</b></li>)}</ol></article><article><h3>收藏最多</h3><ol>{data.topFavorites.map((x:any)=><li key={x.title}><span>{x.title}</span><b>{x._count.title}</b></li>)}</ol></article><article><h3>最近用户</h3><ol>{data.recentUsers.map((x:any)=><li key={x.id}><span>{x.displayName||x.username}</span><small>{timeAgo(x.createdAt)}</small></li>)}</ol></article></div></AdminFrame>}
function AdminSettings(){const defaults={siteName:'',logoUrl:'',faviconUrl:'',siteDescription:'',seoTitle:'',seoDescription:'',footerText:'',copyrightText:'',noticeText:'',noticeEnabled:'true',themePreset:'netflix',accentColor:'#e50914',cardRadius:'8',headerOpacity:'88',heroEnabled:'true',homeSource:'',danmakuEnabled:'true',realDanmakuEnabled:'true',simulatedDanmakuEnabled:'true',simulatedDanmakuDensity:'medium',lineAliases:'{}',allowRegister:'false'};const [form,setForm]=useState<any>(defaults);const [sources,setSources]=useState<any[]>([]);const [saved,setSaved]=useState(false);useEffect(()=>{api('/settings').then(x=>setForm({...defaults,...x}));api<any[]>('/admin/sources').then(setSources)},[]);const field=(key:string,label:string,type='text')=><label>{label}<input type={type} value={form[key]} onChange={e=>setForm({...form,[key]:e.target.value})}/></label>;const toggle=(key:string,label:string)=><label className="toggle"><input type="checkbox" checked={form[key]!=='false'} onChange={e=>setForm({...form,[key]:String(e.target.checked)})}/><span/>{label}</label>;return <AdminFrame title="网站设置"><div className="settings-sections"><section><h2>品牌与 SEO</h2><div className="admin-form">{field('siteName','网站名称')}{field('logoUrl','Logo 地址')}{field('faviconUrl','Favicon 地址')}{field('siteDescription','网站描述')}{field('seoTitle','SEO 标题')}{field('seoDescription','SEO 描述')}{field('footerText','页脚内容')}{field('copyrightText','版权信息')}</div></section><section><h2>首页内容</h2><div className="admin-form full"><label>默认首页数据源<select value={form.homeSource||''} onChange={e=>setForm({...form,homeSource:e.target.value})}><option value="">首次进入时由用户选择</option>{sources.map(x=><option key={x.key} value={x.key}>{x.name}</option>)}</select></label><p>首页也可以直接点击“首页数据源”切换；这里用于没有选择记录的浏览器。</p></div></section><section><h2>首页公告</h2><div className="admin-form full">{field('noticeText','公告内容')}{toggle('noticeEnabled','显示公告')}{toggle('heroEnabled','显示 Hero Banner')}</div></section><RegistrationSettings/><RatingSettings/><section><h2>主题</h2><div className="admin-form"><label>主题预设<select value={form.themePreset} onChange={e=>setForm({...form,themePreset:e.target.value})}><option value="netflix">Netflix</option><option value="dark">Pure Dark</option><option value="cinema">Cinema</option><option value="compact">Compact</option></select></label>{field('accentColor','强调色','color')}{field('cardRadius','卡片圆角')}{field('headerOpacity','顶部透明度')}</div></section><section><h2>播放与弹幕</h2><div className="admin-form full">{toggle('danmakuEnabled','弹幕总开关')}{toggle('realDanmakuEnabled','真实弹幕')}{toggle('simulatedDanmakuEnabled','模拟弹幕')}<label>模拟弹幕密度<select value={form.simulatedDanmakuDensity} onChange={e=>setForm({...form,simulatedDanmakuDensity:e.target.value})}><option value="low">低</option><option value="medium">中</option><option value="high">高</option></select></label><label>播放器名称映射<input value={form.lineAliases} onChange={e=>setForm({...form,lineAliases:e.target.value})}/></label></div></section><button className="primary" onClick={async()=>{const {allowRegister:_registrationSetting,...websiteSettings}=form;await api('/settings',json(websiteSettings));localStorage.setItem('tvbox.lineAliases',form.lineAliases);setSaved(true)}}>保存全部设置</button>{saved&&<span className="success-message">保存成功，刷新前台后生效</span>}</div></AdminFrame>}
function AdminSources(){return <AdminFrame title="数据源管理"><SourceManagement/></AdminFrame>}
function AdminUsers(){return <AdminFrame title="用户管理"><UserAdmin/></AdminFrame>}
function CollectionCenter(){const location=useLocation();const [sources,setSources]=useState<any[]>([]);const [selected,setSelected]=useState(()=>new URLSearchParams(location.search).get('sourceKey')||'');const [categories,setCategories]=useState<string[]>([]);const [bindings,setBindings]=useState<any[]>([]);const [localCategories,setLocalCategories]=useState<string[]>([]);const [status,setStatus]=useState<any>();const [message,setMessage]=useState('');const [busy,setBusy]=useState(false);const loadSources=()=>api<any[]>('/admin/sources').then(x=>{setSources(x);setSelected(current=>current||x[0]?.key||'')});useEffect(()=>{void loadSources()},[]);useEffect(()=>{if(!selected)return;setMessage('');api<any>(`/admin/sources/${selected}/collection-info`).then(x=>{setCategories(x.categories);setBindings(x.bindings.map((b:any)=>({...b})));setLocalCategories(x.localCategories);setStatus(x.status)}).catch(e=>setMessage(e.message))},[selected]);useEffect(()=>{if(!selected)return;const timer=window.setInterval(()=>api<any>(`/admin/sources/${selected}/collection-status`).then(setStatus).catch(()=>{}),1000);return()=>clearInterval(timer)},[selected]);const bindingFor=(remoteCategory:string)=>bindings.find(x=>x.remoteCategory===remoteCategory);const setBinding=(remoteCategory:string,localCategory:string)=>setBindings(current=>[...current.filter(x=>x.remoteCategory!==remoteCategory),...(localCategory?[{remoteCategory,localCategory,enabled:true}]:[])]);const autoBind=()=>setBindings(categories.map(remoteCategory=>({remoteCategory,localCategory:guessCategory(remoteCategory,localCategories),enabled:true})).filter(x=>x.localCategory));const addCategory=async()=>{const name=window.prompt('请输入本站分类名称');if(!name?.trim())return;const next=[...new Set([...localCategories,name.trim()])];try{await api('/admin/categories',json({categories:next}));setLocalCategories(next);setMessage(`已添加分类：${name.trim()}`)}catch(e:any){setMessage(e.message)}};const save=async()=>{setBusy(true);try{await api(`/admin/sources/${selected}/category-bindings`,{...json({bindings}),method:'PUT'});setMessage('分类绑定已保存')}catch(e:any){setMessage(e.message)}finally{setBusy(false)}};const collect=async(mode:'incremental'|'all')=>{setBusy(true);try{const x=await api(`/admin/sources/${selected}/collect`,json({mode,limit:mode==='all'?0:500}));setMessage(x.message);setStatus((await api(`/admin/sources/${selected}/collection-status`)))}catch(e:any){setMessage(e.message)}finally{setBusy(false)}};return <AdminFrame title="本地采集"><div className="collection-intro"><b>远程源 → 分类绑定 → 本地内容库</b><p>绑定后才会入库。影片、封面、简介、播放线路和剧集保存到本机数据库，前台优先读取本地内容。</p></div><div className="collection-toolbar"><label>选择数据源<select value={selected} onChange={e=>setSelected(e.target.value)}>{sources.map(x=><option key={x.key} value={x.key}>{x.name}</option>)}</select></label><button onClick={autoBind} disabled={!categories.length}>自动绑定同名分类</button><button onClick={addCategory}>＋ 手动添加分类</button><button onClick={()=>void save()} disabled={busy||!selected}>保存分类绑定</button></div>{selected&&<section className="binding-panel"><div className="binding-head"><h2>采集分类绑定</h2><span>{categories.length} 个资源站分类 · {localCategories.length} 个本站分类</span></div>{!categories.length?<Spinner label="正在读取远程分类"/>:<div className="binding-list">{categories.map(remoteCategory=>{const row=bindingFor(remoteCategory);return <div className="binding-row" key={remoteCategory}><span>{remoteCategory}</span><b>→</b><select value={row?.localCategory||''} onChange={e=>setBinding(remoteCategory,e.target.value)}><option value="">不采集</option>{localCategories.map(x=><option key={x} value={x}>{x}</option>)}</select></div>})}</div>}</section>}{status&&<section className="collection-status"><div><small>本地已入库</small><strong>{status.collectedCount||0}</strong></div><div><small>采集状态</small><strong>{status.running||status.collectionStatus==='running'?'采集中…':status.collectionStatus==='error'?'失败':'空闲'}</strong>{status.progress&&<small>{status.progress.processed||0} / {status.progress.total||'…'} · 第 {status.progress.page||0} 页</small>}</div><div><small>上次采集</small><strong>{status.lastCollectedAt?timeAgo(status.lastCollectedAt):'尚未采集'}</strong></div></section>}<div className="collection-actions"><button className="primary" disabled={busy||!selected} onClick={()=>void collect('incremental')}>采集最近一页</button><button disabled={busy||!selected} onClick={()=>void collect('all')}>采集全部（不设数量上限）</button>{status?.running&&<button className="danger-text" onClick={async()=>{await api(`/admin/sources/${selected}/collect/cancel`,{method:'POST'});setMessage('已发送取消请求')}}>取消采集</button>}</div><SchedulePanel/>{message&&<p className="success-message">{message}</p>}</AdminFrame>}
function AdminList({kind,title}:{kind:'history'|'errors'|'logs';title:string}){const [items,setItems]=useState<any[]>();useEffect(()=>{api<any[]>(`/admin/${kind}`).then(setItems)},[kind]);return <AdminFrame title={title}>{!items?<Spinner/>:items.length?<div className="log-list">{items.map((x:any)=><div key={x.id}><i className={`status ${kind==='errors'?'bad':'good'}`}/><div><b>{x.title||x.action||x.errorType}</b><p>{x.username||x.sourceKey} · {x.episodeName||x.errorMessage||x.detail||'无详细信息'}</p></div><time>{timeAgo(x.updatedAt||x.createdAt)}</time></div>)}</div>:<Empty title="暂无记录"/>}</AdminFrame>}
function AdminDanmaku(){const [items,setItems]=useState<any[]>();const [words,setWords]=useState('');const load=()=>api<any[]>('/admin/danmaku').then(setItems);useEffect(()=>{void load()},[]);return <AdminFrame title="弹幕管理"><div className="simulated-box"><h3>模拟弹幕词库</h3><textarea value={words} onChange={e=>setWords(e.target.value)} placeholder="每行一条弹幕，可批量导入"/><button onClick={async()=>{await api('/admin/danmaku/simulated',json({content:words,episodeId:'global'}));setWords('');load()}}>批量导入</button></div>{!items?<Spinner/>:<div className="log-list">{items.map(x=><div key={x.id}><i className={`status ${x.enabled?'good':'bad'}`}/><div><b>{x.content}</b><p>{x.simulated?'模拟弹幕':'真实弹幕'} · {x.episodeId}</p></div><button onClick={async()=>{await api(`/admin/danmaku/${x.id}`,{method:'DELETE'});load()}}>删除</button></div>)}</div>}</AdminFrame>}
function SourceEditor(){const [config,setConfig]=useState<any>({name:'大彪TV',sites:[]});const [message,setMessage]=useState('');useEffect(()=>{api('/config').then(setConfig)},[]);const importLocal=async()=>{try{const result=await api<any>('/config/import-local',{method:'POST'});setMessage(`已从 tvbox.json 恢复 ${result.sites} 个播放源`);setConfig(await api('/config'))}catch(error:any){setMessage(error.message)}};return <AdminFrame title="源配置"><div className="source-editor"><label>配置名称<input value={config.name||''} onChange={e=>setConfig({...config,name:e.target.value})}/></label><div className="admin-actions"><p>数据库连接由启动时的 .env 中 DATABASE_URL 决定；下面的源配置保存到 SQLite。</p><button onClick={()=>void importLocal()}>从 tvbox.json 恢复</button></div>{config.sites.map((x:any,i:number)=><div className="source-edit-row" key={i}><input value={x.name} onChange={e=>setConfig({...config,sites:config.sites.map((s:any,n:number)=>n===i?{...s,name:e.target.value}:s)})}/><input value={x.api} onChange={e=>setConfig({...config,sites:config.sites.map((s:any,n:number)=>n===i?{...s,api:e.target.value}:s)})}/><button onClick={()=>setConfig({...config,sites:config.sites.filter((_:any,n:number)=>n!==i)})}>删除</button></div>)}<button onClick={()=>setConfig({...config,sites:[...config.sites,{key:`source_${Date.now()}`,name:'新数据源',type:'tvbox-json',api:'',searchable:1,quickSearch:1,filterable:1}]})}>＋ 添加数据源</button><button className="primary" onClick={async()=>{await api('/config',json({rawConfig:JSON.stringify(config)}));setMessage('数据源配置已保存')}}>保存配置</button>{message&&<span className="success-message">{message}</span>}</div></AdminFrame>}

export default function App(){const path=useLocation().pathname;useEffect(()=>{document.documentElement.dataset.surface=path.startsWith('/admin')?'admin':'site'},[path]);const chrome=!path.startsWith('/admin')&&path!='/login'&&path!='/install'&&path!='/register';const [user,setUser]=useState<User|null|undefined>(undefined);const [installation,setInstallation]=useState<any>(null);const [settings,setSettings]=useState<Settings>({siteName:'大彪TV',logoUrl:'/images/dabiao-logo.svg',faviconUrl:'/images/dabiao-icon.svg'});useEffect(()=>{Promise.all([api<any>('/install/status'),api<User|null>('/auth/me'),api<Settings>('/settings')]).then(([status,u,s])=>{setInstallation(status);setUser(u);setSettings(s);if(s.lineAliases)localStorage.setItem('tvbox.lineAliases',s.lineAliases);document.documentElement.style.setProperty('--accent',s.accentColor||'#e50914');document.documentElement.style.setProperty('--radius',`${s.cardRadius||8}px`);document.title=s.seoTitle||s.siteName||'大彪TV';document.documentElement.dataset.theme=s.themePreset||'netflix';if(s.faviconUrl){let link=document.querySelector("link[rel='icon']") as HTMLLinkElement|null;if(!link){link=document.createElement('link');link.rel='icon';document.head.appendChild(link)}link.href=s.faviconUrl}}).catch(()=>{setInstallation({installed:false});setUser(null)})},[]);useEffect(()=>{if(!installation?.installed)return;let active=true;const refresh=()=>api<User|null>('/auth/me').then(value=>{if(active)setUser(value)}).catch(()=>{});void refresh();const onFocus=()=>{if(document.visibilityState==='visible')void refresh()};window.addEventListener('dbtv:account-updated',refresh);window.addEventListener('focus',onFocus);const timer=window.setInterval(onFocus,60000);return()=>{active=false;window.clearInterval(timer);window.removeEventListener('dbtv:account-updated',refresh);window.removeEventListener('focus',onFocus)}},[path,installation?.installed]);if(!installation)return <Spinner label="正在检查安装状态"/>;if(!installation.installed)return <Install settings={settings} status={installation}/>;const logout=async()=>{await api('/auth/logout',{method:'POST'});setUser(null)};return <>{chrome&&<Header user={user||null} settings={settings} onLogout={logout}/>}<Routes><Route path="/install" element={<Navigate to="/" replace/>}/><Route path="/register" element={user?<Navigate to="/membership"/>:<Register settings={settings}/>}/><Route path="/membership" element={<Guard user={user}><Membership/></Guard>}/><Route path="/admin/membership" element={<Guard user={user} admin><AdminFrame title="会员与积分"><MembershipAdmin/></AdminFrame></Guard>}/><Route path="/login" element={user?<Navigate to="/"/>:<Login settings={settings}/>}/><Route path="/" element={<Guard user={user}><Home settings={settings} user={user}/></Guard>}/><Route path="/sources" element={<Guard user={user}><Sources/></Guard>}/><Route path="/source/:key" element={<Guard user={user}><Source/></Guard>}/><Route path="/detail/:sourceKey/:videoId" element={<Guard user={user}><Detail/></Guard>}/><Route path="/player/:sourceKey/:videoId/:episodeId" element={<Guard user={user}><Player settings={settings}/></Guard>}/><Route path="/recommendations" element={<Guard user={user}><Recommendations/></Guard>}/><Route path="/discover" element={<Guard user={user}><DiscoverPage/></Guard>}/><Route path="/category/:category" element={<Guard user={user}><CategoryRoute/></Guard>}/><Route path="/search" element={<Guard user={user}><Search/></Guard>}/><Route path="/favorites" element={<Guard user={user}><Favorites/></Guard>}/><Route path="/history" element={<Guard user={user}><History/></Guard>}/><Route path="/profile" element={<Guard user={user}>{user&&<Profile user={user}/>}</Guard>}/><Route path="/admin" element={<Guard user={user} admin><AdminDashboard/></Guard>}/><Route path="/admin/settings" element={<Guard user={user} admin><AdminSettings/></Guard>}/><Route path="/admin/updates" element={<Guard user={user} admin><AdminFrame title="系统更新"><SystemUpdates/></AdminFrame></Guard>}/><Route path="/admin/resource-center" element={<Guard user={user} admin><AdminFrame title="资源中心"><ResourceCenter/></AdminFrame></Guard>}/><Route path="/admin/sources" element={<Guard user={user} admin><AdminSources/></Guard>}/><Route path="/admin/collection" element={<Guard user={user} admin><CollectionCenter/></Guard>}/><Route path="/admin/categories" element={<Guard user={user} admin><CategoryManager/></Guard>}/><Route path="/admin/videos" element={<Guard user={user} admin><VideoManager/></Guard>}/><Route path="/admin/editor" element={<Guard user={user} admin><SourceEditor/></Guard>}/><Route path="/admin/users" element={<Guard user={user} admin><AdminUsers/></Guard>}/><Route path="/admin/history" element={<Guard user={user} admin><AdminList kind="history" title="观看统计"/></Guard>}/><Route path="/admin/danmaku" element={<Guard user={user} admin><AdminDanmaku/></Guard>}/><Route path="/admin/errors" element={<Guard user={user} admin><AdminList kind="errors" title="播放错误"/></Guard>}/><Route path="/admin/logs" element={<Guard user={user} admin><AdminList kind="logs" title="系统日志"/></Guard>}/><Route path="*" element={<Navigate to="/" replace/>}/></Routes>{chrome&&<footer><RatingCredits/>{settings.footerText||settings.copyrightText||'大彪TV · 仅用于播放你拥有授权的内容'}</footer>}</>}
